style.css:
/* =========================================================
   ULTIMATE KRISTEN ITC FORCER
   Forces Kristen ITC on basically every website, including Google.
   Because apparently the internet needed to look like a birthday card.
   ========================================================= */

/* Load font from your computer */
@font-face {
    font-family: "Kristen ITC";
    src: local("Kristen ITC");
}

/* Apply to EVERYTHING */
html,
body,
body *,
body *::before,
body *::after,
input,
textarea,
select,
button,
option,
label,
span,
div,
p,
a,
li,
td,
th,
h1,
h2,
h3,
h4,
h5,
h6 {
    font-family: "Kristen ITC" !important;
}

/* Google sometimes uses special classes and variables */
:root {
    --gm3-font-family: "Kristen ITC" !important;
    --google-font-family: "Kristen ITC" !important;
}

/* Fix form controls */
input,
textarea,
button,
select {
    font-family: "Kristen ITC" !important;
}

/* Force iframes that inherit styles */
iframe {
    font-family: "Kristen ITC" !important;
}
